// Session-handshake auth implementation for synology.
//
// Flow:
//   1. GET  — seed cookies (if bootstrap URL is configured)
//   2. GET https://nas.example.com:5001/webapi/entry.cgi?api=SYNO.API.Auth&method=login&version=7 — receive anti-CSRF token
//   3. Attach token to every request via query param _sid
//   4. On responses, invalidate and re-fetch
//
// The manager persists to the CLI data directory so the token
// survives across invocations (TTL: 1 hours).
// Cookies from the jar are scoped to the requesting host automatically via
// net/http/cookiejar.

package client

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/cookiejar"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/mvanhorn/printing-press-library/library/devices/synology/internal/cliutil"
)

const (
	sessionBootstrapURL  = ""
	sessionTokenURL      = "https://nas.example.com:5001/webapi/entry.cgi?api=SYNO.API.Auth&method=login&version=7"
	sessionDataBaseURL   = "https://nas.example.com:5001"
	sessionTokenFormat   = "text"
	sessionTokenJSONPath = ""
	sessionUserAgent     = "Mozilla/5.0 (compatible; synology-pp-cli)"
)

var sessionTTL = 1 * time.Hour

// sessionInvalidationStatuses are HTTP status codes that trigger token
// invalidation. When the server returns one of these, the cached token is
// cleared so the next request re-bootstraps.
var sessionInvalidationStatuses = map[int]bool{
	401: true,
	403: true,
}

// SessionManager owns the cookie jar + cached token and coordinates the
// handshake. Safe for concurrent use by the client's retry loop.
//
// HAND-AUTHORED FIELDS: baseURL and synoToken. DSM's login target is
// per-installation, so the handshake resolves it from the user's configured
// base URL instead of the compile-time sessionTokenURL constant, and DSM
// answers with a second credential (the SynoToken) that rides along as a
// header. See synology.go.
type SessionManager struct {
	mu         sync.Mutex
	client     *http.Client
	jar        http.CookieJar
	token      string
	synoToken  string
	baseURL    string
	configPath string
}

// newSessionManager constructs a SessionManager with a cookie jar attached to
// its HTTP client. Any cached session on disk is loaded immediately.
//
// The bootstrap and token-fetch calls go through the same newHTTPClient as the
// data path so a browser-impersonated transport (Surf, when configured) is
// applied to the handshake itself — otherwise the very calls that establish
// the session run as a vanilla net/http client and get rate-limited away
// even when the data client would have cleared the bot wall.
func newSessionManager(timeout time.Duration, configPath, baseURL string, insecureTLS bool) *SessionManager {
	jar, _ := cookiejar.New(nil)
	m := &SessionManager{
		jar:        jar,
		client:     newHTTPClient(timeout, jar, insecureTLS),
		baseURL:    baseURL,
		configPath: configPath,
	}
	m.loadFromDisk()
	return m
}

// AttachTo hooks this SessionManager's cookie jar onto the shared client so
// every data request reuses the bootstrapped cookies.
func (m *SessionManager) AttachTo(c *http.Client) {
	if c.Jar == nil {
		c.Jar = m.jar
	}
}

func (m *SessionManager) CookieJar() http.CookieJar {
	return m.jar
}

// Token returns the cached token without triggering a network call. Empty
// string when no session is established or the cache was invalidated.
func (m *SessionManager) Token() string {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.token
}

// EnsureToken returns a valid session id, logging in again if the cache is
// empty or was invalidated. The network calls happen under the manager's lock
// — concurrent callers wait for a single in-flight handshake.
//
// HAND-AUTHORED BODY. The generic handshake GETs a compile-time URL and takes
// the whole response body as the token; DSM needs a credential exchange
// against the user's own NAS. Credentials come from the environment so an
// expired session can heal itself mid-run.
//
// A run with no credentials in scope returns an empty token rather than an
// error: SYNO.API.Info and a few other calls answer without a session at all,
// and for the calls that do need one DSM's own error 105/119 carries a better
// message than a transport-level guess. classifyAPIError turns those into the
// "run session login" hint.
func (m *SessionManager) EnsureToken() (string, error) {
	m.mu.Lock()
	if m.token != "" {
		t := m.token
		m.mu.Unlock()
		return t, nil
	}
	base := m.baseURL
	m.mu.Unlock()

	creds := dsmCredentialsFromEnv()
	if !creds.complete() || strings.TrimSpace(base) == "" {
		return "", nil
	}

	res, err := m.dsmLogin(base, creds)
	if err != nil {
		return "", err
	}
	return res.SID, nil
}

// dsmLogin performs the SYNO.API.Auth login and caches both credentials it
// returns. HAND-AUTHORED.
func (m *SessionManager) dsmLogin(baseURL string, creds dsmCredentials) (dsmLoginResult, error) {
	var out dsmLoginResult
	// The login URL carries the password as a query parameter, and both
	// http.NewRequest and client.Do quote that URL in the errors they return,
	// so every error leaving this function is scrubbed.
	req, err := http.NewRequest("GET", dsmLoginURL(baseURL, creds), nil)
	if err != nil {
		return out, scrubDSMSecretError(fmt.Errorf("DSM login: %w", err))
	}
	req.Header.Set("User-Agent", sessionUserAgent)
	req.Header.Set("Accept", "application/json")
	resp, err := m.client.Do(req)
	if err != nil {
		return out, scrubDSMSecretError(fmt.Errorf("DSM login: %w", err))
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return out, fmt.Errorf("reading DSM login response: %w", err)
	}
	if resp.StatusCode >= 400 {
		return out, fmt.Errorf("DSM login endpoint returned HTTP %d", resp.StatusCode)
	}
	out, err = parseDSMLogin(body)
	if err != nil {
		return out, err
	}
	m.SetSession(out)
	return out, nil
}

// SetSession caches a sid plus SynoToken and persists them. Used by the
// handshake above and by `session login` so an interactive login leaves a
// session behind for later commands. HAND-AUTHORED.
func (m *SessionManager) SetSession(res dsmLoginResult) {
	m.mu.Lock()
	m.token = res.SID
	m.synoToken = res.SynoToken
	m.mu.Unlock()
	m.saveToDisk()
}

// SynoToken returns the cached anti-CSRF token DSM 7.3.2+ requires on calls
// that change state. Empty when no session is established. HAND-AUTHORED.
func (m *SessionManager) SynoToken() string {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.synoToken
}

// Clear drops the cached session and removes it from disk. HAND-AUTHORED.
func (m *SessionManager) Clear() {
	m.mu.Lock()
	m.token = ""
	m.synoToken = ""
	m.mu.Unlock()
	if path := m.sessionFilePath(); path != "" {
		_ = os.Remove(path)
	}
}

// ShouldInvalidate returns true when an HTTP status code indicates the token
// was rejected and the session should be re-bootstrapped.
func (m *SessionManager) ShouldInvalidate(statusCode int) bool {
	return sessionInvalidationStatuses[statusCode]
}

// Invalidate clears the cached token so the next EnsureToken re-bootstraps.
func (m *SessionManager) Invalidate() {
	m.mu.Lock()
	m.token = ""
	m.mu.Unlock()
}

// ImportSession accepts cookies + a token captured from a real browser session
// (e.g. Chrome DevTools) and treats them as a live session. Used when the
// server-side handshake is rate-limited from the user's IP.
func (m *SessionManager) ImportSession(cookieDomain string, cookies []*http.Cookie, token string) error {
	if m.jar == nil {
		return fmt.Errorf("no cookie jar attached")
	}
	u, err := url.Parse(cookieDomain)
	if err != nil {
		return fmt.Errorf("invalid cookie domain: %w", err)
	}
	for _, ck := range cookies {
		if ck == nil {
			continue
		}
		target := u
		if ck.Domain != "" {
			if parsed, err := url.Parse("https://" + strings.TrimPrefix(ck.Domain, ".")); err == nil {
				target = parsed
			}
		}
		m.jar.SetCookies(target, []*http.Cookie{ck})
	}
	m.mu.Lock()
	m.token = token
	m.mu.Unlock()
	m.saveToDisk()
	return nil
}

// --- Persistence helpers ---

func (m *SessionManager) sessionFilePath() string {
	dir, err := cliutil.DataDir()
	if err != nil {
		return ""
	}
	return filepath.Join(dir, "session.json")
}

// SynoToken is hand-added: DSM issues a second, header-borne credential
// alongside the session id, and both have to survive between invocations.
// Neither is a password; the account password is never written to this file.
type sessionRecord struct {
	Token     string      `json:"token"`
	SynoToken string      `json:"synotoken,omitempty"`
	Cookies   []jarCookie `json:"cookies"`
	Saved     time.Time   `json:"saved"`
}

type jarCookie struct {
	URL     string    `json:"url"`
	Name    string    `json:"name"`
	Value   string    `json:"value"`
	Path    string    `json:"path"`
	Expires time.Time `json:"expires,omitempty"`
}

func (m *SessionManager) loadFromDisk() {
	path := m.sessionFilePath()
	if path == "" {
		return
	}
	legacy := ""
	if m.configPath != "" {
		legacy = filepath.Join(filepath.Dir(m.configPath), "session.json")
	}
	data, _, err := cliutil.ReadFileWithLegacyFallback(path, legacy)
	if err != nil {
		return
	}
	var rec sessionRecord
	if err := json.Unmarshal(data, &rec); err != nil {
		return
	}
	if time.Since(rec.Saved) > sessionTTL {
		return // stale; ignore
	}
	m.mu.Lock()
	m.token = rec.Token
	m.synoToken = rec.SynoToken
	m.mu.Unlock()
	for _, c := range rec.Cookies {
		u, err := url.Parse(c.URL)
		if err != nil || m.jar == nil {
			continue
		}
		ck := &http.Cookie{
			Name:    c.Name,
			Value:   c.Value,
			Path:    c.Path,
			Expires: c.Expires,
		}
		m.jar.SetCookies(u, []*http.Cookie{ck})
	}
}

func (m *SessionManager) saveToDisk() {
	path := m.sessionFilePath()
	if path == "" || m.jar == nil {
		return
	}
	m.mu.Lock()
	tok := m.token
	synoTok := m.synoToken
	base := m.baseURL
	m.mu.Unlock()

	// Persist cookies for every host the session interacts with. cookiejar
	// strips Domain on Cookies(u), so a single-host snapshot drops cookies
	// scoped to a parent domain that other hosts in the handshake also rely
	// on. Re-snapshot per host so each destination has the cookies it needs
	// after restore.
	var cookies []jarCookie
	seen := make(map[string]bool)
	// base is hand-added: the NAS address is per-user, so the placeholder
	// constants below never match the host the cookies actually came from.
	for _, host := range []string{base, sessionBootstrapURL, sessionTokenURL, sessionDataBaseURL} {
		if host == "" {
			continue
		}
		u, err := url.Parse(host)
		if err != nil || u.Host == "" {
			continue
		}
		rootURL := u.Scheme + "://" + u.Host + "/"
		for _, ck := range m.jar.Cookies(u) {
			key := rootURL + "|" + ck.Name + "=" + ck.Value
			if seen[key] {
				continue
			}
			seen[key] = true
			cookies = append(cookies, jarCookie{
				URL:     rootURL,
				Name:    ck.Name,
				Value:   ck.Value,
				Path:    ck.Path,
				Expires: ck.Expires,
			})
		}
	}
	rec := sessionRecord{Token: tok, SynoToken: synoTok, Cookies: cookies, Saved: time.Now()}
	data, err := json.MarshalIndent(rec, "", "  ")
	if err != nil {
		return
	}
	// Hand-added: the session record holds a live sid and SynoToken, so it gets
	// the same atomic, permission-enforcing write config.json uses. os.WriteFile
	// truncates in place and only applies its mode when it creates the file, so
	// it can both corrupt the record mid-write and leave a pre-existing file at
	// looser permissions.
	_ = cliutil.AtomicWritePrivateFile(path, data, 0o600, 0o700)
}

// extractJSONToken pulls a token from a JSON body by dot-separated path.
// Example: ("data.token", `{"data":{"token":"abc"}}`) → "abc". Empty string on
// parse failure or missing field.
func extractJSONToken(body []byte, path string) string {
	var obj any
	if err := json.Unmarshal(body, &obj); err != nil {
		return ""
	}
	if path == "" {
		if s, ok := obj.(string); ok {
			return s
		}
		return ""
	}
	cur := obj
	for _, part := range strings.Split(path, ".") {
		m, ok := cur.(map[string]any)
		if !ok {
			return ""
		}
		cur = m[part]
	}
	if s, ok := cur.(string); ok {
		return s
	}
	return ""
}
